// Find the shortest palindrome that begins with a supplied string.
// Algorithm idea is simple:
// - Find the longest postfix of supplied string that is a palindrome.
// - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
// >>> make_palindrome((""))
// ("")
// >>> make_palindrome(("cat"))
// ("catac")
// >>> make_palindrome(("cata"))
// ("catac")
std::string make_palindrome(std::string string) {
    // Find the longest palindromic suffix
    int len = string.size();
    int i = 0;
    while (i < len) {
        if (string[i] == string[len - 1 - i]) {
            i++;
        } else {
            break;
        }
    }
    // i is the length of the palindromic suffix
    // So the prefix is string[0...i-1]
    std::string prefix = string.substr(0, i);
    std::string reversed_prefix = prefix;
    std::reverse(reversed_prefix.begin(), reversed_prefix.end());
    return string + reversed_prefix;

