    // Sort the numbers
    std::sort(numbers.begin(), numbers.end());
    // Initialize the minimum difference to a large value
    float min_diff = std::numeric_limits<float>::max();
    // Initialize the closest pair
    std::tuple<float, float> closest_pair;
    // Iterate through the sorted numbers
    for (int i = 0; i < numbers.size() - 1; i++) {
        // Calculate the difference between the current number and the next number
        float diff = numbers[i + 1] - numbers[i];
        // If the difference is smaller than the current minimum difference
        if (diff < min_diff) {
            // Update the minimum difference
            min_diff = diff;
            // Update the closest pair
            closest_pair = std::make_tuple(numbers[i], numbers[i + 1]);
        }
    }
    // Return the closest pair
    return closest_pair;

