// (1)
long modp(long n, long p) {
    if (n == 0) return 1;
    long res = 1;
    n = n % p;
    while (n > 0) {
        if (n % 2 == 1) {
            res = (res * n) % p;
        }
        n = n / 2;
        n = (n * n) % p;
    }
    return res;

