// Add two numbers x and y
// >>> add((2), (3))
// (5)
// >>> add((5), (7))
// (12)
long add(long x, long y) {
    long carry = (x & y) << 1;
    long sum = x ^ y;
    while (carry != 0) {
        long new_carry = (sum & carry) << 1;
        long new_sum = sum ^ carry;
        sum = new_sum;
        carry = new_carry;
    }
    return sum;

