        long num = arr[i];
        long sum = 0;
        bool isNegative = false;
        if (num < 0) {
            isNegative = true;
            num = -num;
        }
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        if (isNegative) {
            sum = -sum;
        }
