// It must be implemented like this:
// >>> sort_array((std::vector<long>({(long)1, (long)5, (long)2, (long)3, (long)4})))
// (std::vector<long>({(long)1, (long)2, (long)3, (long)4, (long)5}))
// >>> sort_array((std::vector<long>({(long)-2, (long)-3, (long)-4, (long)-5, (long)-6})))
// (std::vector<long>({(long)-6, (long)-5, (long)-4, (long)-3, (long)-2}))
// >>> sort_array((std::vector<long>({(long)1, (long)0, (long)2, (long)3, (long)4})))
// (std::vector<long>({(long)0, (long)1, (long)2, (long)3, (long)4}))
std::vector<long> sort_array(std::vector<long> arr) {
    std::sort(arr.begin(), arr.end(), [&](long a, long b) {
        int countA = 0, countB = 0;
        long tempA = a, tempB = b;
        while (tempA != 0) {
            tempA = tempA & (tempA - 1);
            countA++;
        }
        while (tempB != 0) {
            tempB = tempB & (tempB - 1);
            countB++;
        }
        if (countA != countB) return countA < countB;
        else return a < b;
    });
    return arr;

