    int n = b.size();
    if (n > a.size()) return false;
    for (int i = 0; i < n; i++) {
        std::string rotation = b.substr(i) + b.substr(0, i);
        if (a.find(rotation) != std::string::npos) {
            return true;
        }
    }
    return false;

