// ("cdxxvi")
std::string int_to_mini_roman(long number) {
    std::string result;
    std::vector<std::pair<int, std::string>> roman_numerals = {
        {1000, "m"},
        {900, "cm"},
        {500, "d"},
        {400, "cd"},
        {100, "c"},
        {90, "xc"},
        {50, "l"},
        {40, "xl"},
        {10, "x"},
        {9, "ix"},
        {5, "v"},
        {4, "iv"},
        {1, "i"}
    };
    for (auto& pair : roman_numerals) {
        int value = pair.first;
        std::string symbol = pair.second;
        while (number >= value) {
            result += symbol;
            number -= value;
        }
    }
    return result;

