// ("aaaaaaa")
std::string find_max(std::vector<std::string> words) {
    std::string max_str = "";
    int max_unique = 0;
    for (auto word : words) {
        int unique = 0;
        std::set<char> s;
        for (auto c : word) {
            s.insert(c);
        }
        unique = s.size();
        if (unique > max_unique || (unique == max_unique && word < max_str)) {
            max_unique = unique;
            max_str = word;
        }
    }
    return max_str;

