// you should return a vector of [ total number of eaten carrots after your meals,
// the number of carrots left after your meals ]
// if there are not enough remaining carrots, you will eat all remaining carrots, but will still be hungry.
// Example:
// >>> eat((5), (6), (10))
// (std::vector<long>({(long)11, (long)4}))
// >>> eat((4), (8), (9))
// (std::vector<long>({(long)12, (long)1}))
// >>> eat((1), (10), (10))
// (std::vector<long>({(long)11, (long)0}))
// >>> eat((2), (11), (5))
// (std::vector<long>({(long)7, (long)0}))
// Variables:
// @number : integer
// the number of carrots that you have eaten.
// @need : integer
// the number of carrots that you need to eat.
// @remaining : integer
// the number of remaining carrots thet exist in stock
// Constrain:
// * 0 <= number <= 1000
// * 0 <= need <= 1000
// * 0 <= remaining <= 1000
// Have fun :)
std::vector<long> eat(long number, long need, long remaining) {
    long total = number + need;
    long left = remaining - need;
    if (left < 0) {
        total = number + remaining;
        left = 0;
    }
    return {total, left};

